import{DesignSystemManager as e}from"../../d-d-d/lib/DesignSystemManager.js";import{FluentTokens as t,FluentFonts as n}from"./FluentTokens.js";import{FluentDDDMap as s,FluentColorNames as r}from"./FluentDDDMap.js";import{FluentIcons as o}from"./FluentIcons.js";export const FLUENT_SYSTEM="fluent";export function registerFluentDesignSystem(i=e){return i&&!i.systems.fluent&&i.addDesignSystem({name:"fluent",extends:"ddd",styles:[t,s],fonts:n,colorNames:r,icons:o}),i}export function activateFluentDesignSystem(t=e){return registerFluentDesignSystem(t),t&&"fluent"!==t.active&&(t.active="fluent"),t}